use ra_parser::{FragmentKind, ParseError, TreeSink};
use ra_syntax::{
    ast, tokenize, AstToken, NodeOrToken, Parse, SmolStr, SyntaxKind, SyntaxKind::*, SyntaxNode,
    SyntaxTreeBuilder, TextRange, TextUnit, T,
};
use rustc_hash::FxHashMap;
use std::iter::{once, repeat, successors};
use tt::buffer::{Cursor, TokenBuffer};

use crate::subtree_source::SubtreeTokenSource;
use crate::ExpandError;

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum TokenTextRange {
    Token(TextRange),
    Delimiter(TextRange, TextRange),
}

impl TokenTextRange {
    pub fn by_kind(self, kind: SyntaxKind) -> Option<TextRange> {
        match self {
            TokenTextRange::Token(it) => Some(it),
            TokenTextRange::Delimiter(open, close) => match kind {
                T!['{'] | T!['('] | T!['['] => Some(open),
                T!['}'] | T![')'] | T![']'] => Some(close),
                _ => None,
            },
        }
    }
}

/// Maps `tt::TokenId` to the relative range of the original token.
#[derive(Debug, PartialEq, Eq, Default)]
pub struct TokenMap {
    /// Maps `tt::TokenId` to the *relative* source range.
    entries: Vec<(tt::TokenId, TokenTextRange)>,
}

impl TokenMap {
    pub fn token_by_range(&self, relative_range: TextRange) -> Option<tt::TokenId> {
        let &(token_id, _) = self.entries.iter().find(|(_, range)| match range {
            TokenTextRange::Token(it) => *it == relative_range,
            TokenTextRange::Delimiter(open, close) => {
                *open == relative_range || *close == relative_range
            }
        })?;
        Some(token_id)
    }

    pub fn range_by_token(&self, token_id: tt::TokenId) -> Option<TokenTextRange> {
        let &(_, range) = self.entries.iter().find(|(tid, _)| *tid == token_id)?;
        Some(range)
    }

    fn insert(&mut self, token_id: tt::TokenId, relative_range: TextRange) {
        self.entries.push((token_id, TokenTextRange::Token(relative_range)));
    }

    fn insert_delim(
        &mut self,
        token_id: tt::TokenId,
        open_relative_range: TextRange,
        close_relative_range: TextRange,
    ) {
        self.entries
            .push((token_id, TokenTextRange::Delimiter(open_relative_range, close_relative_range)));
    }

    fn update_close_delim(
        &mut self,
        token_id: tt::TokenId,
        close_relative_range: TextRange,
    ) {
        let &mut (_, ref mut range) =
            self.entries.iter_mut().find(|(tid, _)| *tid == token_id).unwrap();
        let range = match range {
            TokenTextRange::Delimiter(_, close) => close,
            _ => unreachable!(),
        };
        *range = close_relative_range;
    }
}

/// Convert the SyntaxNode to a `TokenTree` (what macro
/// will consume).
pub fn syntax_node_to_token_tree(node: &SyntaxNode) -> Option<(tt::Subtree, TokenMap)> {
    let global_offset = node.text_range().start();
    let mut c = Convertor { alloc: TokenIdAlloc::new(global_offset) };
    let subtree = c.go(node)?;
    Some((subtree, c.alloc.map))
}

/// Convert the syntax node to a `TokenTree` (what macro
/// will consume).
///
/// Note: here there is not AST layer, we just use `tree_src` as the source
/// and mutate a `TokenBuffer`
pub fn parse_to_token_tree(text: &str) -> Option<(tt::Subtree, TokenMap)> {
    let tokens = tokenize(text).0;
    if tokens.iter().any(|it| it.kind == ERROR) {
        return None;
    }

    let mut c = RawConvertor {
        text,
        offset: 0,
        tokens: tokens.into_iter().filter(|it| !it.kind.is_trivia()).peekable(),
        alloc: TokenIdAlloc::new(0.into()),
    };

    let subtree = c.go()?;
    Some((subtree, c.alloc.map))
}
```

