/// Convert the syntax tree (what user has written) to a `TokenTree` (what macro
/// will consume).
pub fn ast_to_token_tree(ast: &impl ast::AstNode) -> Option<(tt::Subtree, TokenMap)> {
    syntax_node_to_token_tree(ast.syntax())
}

/// Convert the syntax node to a `TokenTree` (what macro
/// will consume).
pub fn syntax_node_to_token_tree(node: &SyntaxNode) -> Option<(tt::Subtree, TokenMap)> {
    let global_offset = node.text_range().start();
    let mut c = Convertor { alloc: TokenIdAlloc::new(global_offset) };
    let subtree = c.go(node)?;
    Some((subtree, c.alloc.map))
}

/// Convert the raw text to a `TokenTree` (what macro
/// will consume).
///
/// Note: here there is no AST layer, the file content may not be parseable at
/// all, we just want to extract the `TokenTree` from it.
pub fn parse_to_token_tree(text: &str) -> Option<(tt::Subtree, TokenMap)> {
    let (tokens, errors) = tokenize(text);
    if !errors.is_empty() {
        return None;
    }

    let mut c = RawConvertor {
        text,
        offset: 0,
        tokens: tokens.into_iter().filter(|it| it.kind != WHITESPACE).peekable(),
        alloc: TokenIdAlloc::new(0.into()),
    };

    let subtree = c.go()?;
    Some((subtree, c.alloc.map))
}

