fn postfix_snippet(ctx: &CompletionContext, label: &str, detail: &str, snippet: &str) -> Builder {
    let edit = {
        let receiver_range =
            ctx.dot_receiver.as_ref().expect("no receiver available").syntax().text_range();
        let delete_range = TextRange::from_to(receiver_range.start(), ctx.source_range().end());
        TextEdit::replace(delete_range, snippet.to_string())
    };
    CompletionItem::new(CompletionKind::Postfix, ctx.source_range(), label)
        .lookup_by("lete")
        .detail(detail)
        .snippet_edit(edit)
}

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
enum TryEnum {
    Option,
    Result,
}

impl TryEnum {
    fn from_ty(ty: &hir::Type, db: &impl DefDatabase) -> Option<TryEnum> {
        let name = match ty.as_adt() {
            Some(hir::Adt::Enum(e)) => e.name(db),
            _ => return None,
        };
        match name.to_string().as_str() {
            "Option" => Some(TryEnum::Option),
            "Result" => Some(TryEnum::Result),
            _ => None,
        }
    }
}

