        sema: &Semantics<RootDatabase>,
        edit: &mut TextEditBuilder,
        node: &SyntaxNode,
        replacement: &SyntaxNode,
    ) {
        let original = sema.original_range(node);
        edit.replace(original, replacement.to_string());
    }
}
