+
+impl<'a> RawConvertor<'a> {
+    fn to_leaf(&mut self, kind: SyntaxKind, range: TextRange) -> Option<tt::Leaf> {
+        let text = &self.text[range];
+        let id = self.alloc.alloc(range);
+        Some(match kind {
+            T![true] | T![false] => tt::Leaf::Literal(tt::Literal { text: text.into(), id }),
+            IDENT | LIFETIME => tt::Leaf::Ident(tt::Ident { text: text.into(), id }),
+            k if k.is_keyword() => tt::Leaf::Ident(tt::Ident { text: text.into(), id }),
+            k if k.is_literal() => tt::Leaf::Literal(tt::Literal { text: text.into(), id }),
+            _ => return None,
+        })
+    }
