+    fn go(&mut self) -> Option<tt::Subtree> {
+        let subtree = self.go_inner(None)?;
+        // If the whole input is a single delimited group, report it directly as
+        // the root subtree (mirroring how `ast_to_token_tree` represents a
+        // delimited token tree), instead of wrapping it in a delimiter-less root.
+        if subtree.token_trees.len() == 1 {
+            if let tt::TokenTree::Subtree(inner) = &subtree.token_trees[0] {
+                if inner.delimiter.is_some() {
+                    return Some(inner.clone());
+                }
+            }
+        }
+        Some(subtree)
+    }
