+    fn go_inner(&mut self, close_delim_id: Option<tt::TokenId>) -> Option<tt::Subtree> {
+        let mut token_trees = Vec::new();
+        loop {
+            let range = match self.tokens.peek() {
+                Some(token) => TextRange::offset_len(TextUnit::from_usize(self.offset), token.len),
+                None => break,
+            };
+            let token = self.tokens.next()?;
+            self.offset += token.len.to_usize();
+
+            if token.kind == WHITESPACE {
+                continue;
+            }
+
+            match token.kind {
+                T!['('] | T!['{'] | T!['['] => {
+                    let open_range = range;
+                    let delim_id = self.alloc.alloc_delim(
+                        open_range,
+                        TextRange::from_to(open_range.end(), open_range.end()),
+                    );
+                    let delimiter =
+                        Some(tt::Delimiter { kind: delim_kind(token.kind), id: delim_id });
+                    let mut subtree = self.go_inner(Some(delim_id))?;
+                    subtree.delimiter = delimiter;
+                    token_trees.push(subtree.into());
+                }
+                T![')'] | T!['}'] | T![']'] => {
+                    let close_delim_id = close_delim_id?;
+                    self.alloc.map.update_close_delim(close_delim_id, range);
+                    return Some(tt::Subtree { token_trees, delimiter: None });
