+                        // delimiter is followed by a *node* (the delimited group),
+                        // so it is `Alone`. Closing delimiters, on the other hand,
+                        // are plain tokens, so they keep the punctuation joint.
+                        Some(next) if next.kind.is_punct() && !is_open_delim(next.kind) => {
+                            tt::Spacing::Joint
+                        }
+                        _ => tt::Spacing::Alone,
+                    };
+                    let spacing_iter = std::iter::repeat(tt::Spacing::Joint)
+                        .take(text.len() - 1)
+                        .chain(std::iter::once(last_spacing));
+                    for (char, spacing) in text.chars().zip(spacing_iter) {
+                        token_trees.push(
