/// Replaces the expression of a record field, handling field shorthands while
/// preserving the original source range, so that it also works for usages
/// that originate from macro expansions.
pub(crate) fn replace_record_field_expr(
    sema: &Semantics<RootDatabase>,
    edit: &mut TextEditBuilder,
    field: &ast::RecordField,
    new_expr: ast::Expr,
) {
    if let Some(expr) = field.expr() {
        // Not shorthand, just replace the expression.
        edit.replace(sema.original_range(expr.syntax()).range, new_expr.syntax().to_string());
    } else if let Some(name_ref) = field.name_ref() {
        // Shorthand `record { field }`, rewrite it to `record { field: new_expr }`.
        let new_range = sema.original_range(name_ref.syntax()).range;
        edit.replace(new_range, format!("{}: {}", name_ref.text(), new_expr.syntax().to_string()))
    }
}

