use hir::HirDisplay;
use ra_ide_db::{defs::Definition, search::Reference};
use ra_syntax::{
    ast::{self, make, AstNode, NameOwner, TypeAscriptionOwner},
    TextUnit, TokenAtOffset,
};

use crate::{
    assist_ctx::ActionBuilder,
    utils::replace_record_field_expr,
    Assist, AssistCtx, AssistId,
};

// Assist: promote_local_to_const
//
// Promotes a local variable to a const.
//
// ```
// fn main() {
//     let <|>foo = 123;
//     foo;
// }
// ```
// ->
// ```
// fn main() {
//     const FOO: i32 = 123;
//     FOO;
// }
// ```
pub(crate) fn promote_local_to_const(ctx: AssistCtx) -> Option<Assist> {
    let let_stmt = ctx.find_node_at_offset::<ast::LetStmt>()?;
    let initializer = let_stmt.initializer()?;
    let bind_pat = match let_stmt.pat()? {
        ast::Pat::BindPat(pat) => pat,
        _ => return None,
    };
    if !bind_pat.syntax().text_range().contains_inclusive(ctx.frange.range.start()) {
        return None;
    }
    if bind_pat.is_mutable() || bind_pat.is_ref() {
        return None;
    }
    let name = bind_pat.name()?;

    let local = ctx.sema.to_def(&bind_pat)?;

    let const_ty = match let_stmt.ascribed_type() {
        Some(ty) => ty.syntax().to_string(),
        None => {
            let ty = local.ty(ctx.db);
            if ty.contains_unknown() {
                return None;
            }
            ty.display(ctx.db).to_string()
        }
    };

    let usages = Definition::Local(local).find_usages(ctx.db, None);
    if usages.is_empty() {
        return None;
    }

    let const_name = name.text().to_string().to_uppercase();
    let const_stmt = format!(
        "const {}: {} = {};",
        const_name,
        const_ty,
        initializer.syntax().text()
    );
    let let_range = let_stmt.syntax().text_range();
    let cursor_position = let_range.start() + TextUnit::of_str("const ");

    // Compute the edits for all the usages upfront. Usages inside macro
    // expansions are handled through the original source ranges, so that we
    // never try to mutate syntax from the expanded tree.
    let sema = ctx.sema;
    let usage_edits: Vec<UsageEdit> = usages
        .iter()
        .map(|usage| {
            if let Some(record_field) = record_field_for_usage(&sema, usage) {
                UsageEdit::RecordField {
                    field: record_field,
                    replacement: make::expr_from_text(&const_name),
                }
            } else {
                UsageEdit::Replace { range: usage.file_range.range, text: const_name.clone() }
            }
        })
        .collect();

    ctx.add_assist(
        AssistId("promote_local_to_const"),
        "Promote local to const",
        move |edit| {
            for usage_edit in &usage_edits {
                match usage_edit {
                    UsageEdit::RecordField { field, replacement } => replace_record_field_expr(
                        sema,
                        edit.text_edit_builder(),
                        field,
                        replacement.clone(),
                    ),
                    UsageEdit::Replace { range, text } => edit.replace(*range, text.clone()),
                }
            }
            edit.replace(let_range, const_stmt);
            edit.set_cursor(cursor_position);
        },
    )
}

enum UsageEdit {
    Replace { range: ra_syntax::TextRange, text: String },
    RecordField { field: ast::RecordField, replacement: ast::Expr },
}

/// If the usage is a record field (in the original or an expanded tree),
/// returns the corresponding `RecordField` node, which can be used to replace
/// it via `replace_record_field_expr`.
fn record_field_for_usage(
    sema: &hir::Semantics<ra_ide_db::RootDatabase>,
    usage: &Reference,
) -> Option<ast::RecordField> {
    let file_id = usage.file_range.file_id;
    let offset = usage.file_range.range.start();
    let token = match sema.parse(file_id).syntax().token_at_offset(offset) {
        TokenAtOffset::None => return None,
        TokenAtOffset::Single(token) => token,
        TokenAtOffset::Between(_, token) => token,
    };
    let token = sema.descend_into_macros(token);
    token.parent().ancestors().find_map(ast::RecordField::cast)
}

