        check_assist(
            promote_local_to_const,
            "
fn foo() {
    let x<|> = 0;
    let y = x;
    let z = (x, x, x, x);
}
",
            "
fn foo() {
    const <|>X: i32 = 0;
    let y = X;
    let z = (X, X, X, X);
}
",
        );
    }

    #[test]
    fn usage_in_field_shorthand() {
        check_assist(
            promote_local_to_const,
            "
struct Foo {
    bar: usize,
}

fn main() {
    let <|>bar = 0;
    let foo = Foo { bar };
}
",
            "
struct Foo {
    bar: usize,
}

fn main() {
    const <|>BAR: usize = 0;
    let foo = Foo { bar: BAR };
}
",
        );
    }

    #[test]
    fn usage_in_macro() {
        check_assist(
            promote_local_to_const,
