    }
}

fn baz() -> usize {
    let <|>foo = 2;
    identity![foo]
}
",
            "
macro_rules! identity {
    ($body:expr) => {
        $body
    }
}

fn baz() -> usize {
    const <|>FOO: usize = 2;
    identity![FOO]
}
",
        )
    }

    #[test]
    fn usage_shorthand_in_macro() {
        check_assist(
            promote_local_to_const,
            "
struct Foo {
    foo: usize,
}

macro_rules! identity {
    ($body:expr) => {
        $body
    };
}

fn baz() -> Foo {
    let <|>foo = 2;
    identity![Foo { foo }]
}
",
            "
struct Foo {
    foo: usize,
}

macro_rules! identity {
    ($body:expr) => {
        $body
    };
}

fn baz() -> Foo {
    const <|>FOO: usize = 2;
    identity![Foo { foo: FOO }]
}
",
        )
    }

    #[test]
    fn not_applicable_for_mut_variable() {
        check_assist_not_applicable(
            promote_local_to_const,
            "
fn foo() {
    let mut x<|> = 0;
    x;
}
",
        );
    }

    #[test]
    fn not_applicable_for_unknown_type() {
        check_assist_not_applicable(
            promote_local_to_const,
            "
fn foo() {
    let x<|> = bar();
}
",
        );
    }
}

