// Assist: bool_to_enum
//
// Converts `bool` to a new enum with `True` and `False` variants.
//
// ```
// fn main() {
//     let <|>is_true = true;
//     if is_true {
//         println!("is true");
//     }
// }
// ```
// ->
// ```
// #[derive(PartialEq, Eq)]
// enum Bool { True, False }
//
// fn main() {
//     let is_true = Bool::True;
//     if is_true == Bool::True {
//         println!("is true");
//     }
// }
// ```
pub(crate) fn bool_to_enum(ctx: AssistCtx) -> Option<Assist> {
    let name = ctx.find_node_at_offset::<ast::Name>()?;
    let let_stmt = name.syntax().ancestors().find_map(ast::LetStmt::cast)?;
    let bind_pat = match let_stmt.pat()? {
        ast::Pat::BindPat(pat) => pat,
        _ => return None,
    };
    let local = ctx.sema.to_def(&bind_pat)?;
    if !local.ty(ctx.db).is_bool() {
        return None;
    }

    let initializer = let_stmt.initializer();
    let usages = Definition::Local(local).find_usages(ctx.db, None);

    let var_name = name.text().to_string();
    let sema = ctx.sema;

    ctx.add_assist(AssistId("bool_to_enum"), "Convert to enum", move |edit| {
        if let Some(ty) = let_stmt.ascribed_type() {
            edit.replace(ty.syntax().text_range(), "Bool".to_string());
        }

        if let Some(initializer) = &initializer {
            edit.replace(initializer.syntax().text_range(), bool_expr_to_enum_expr(initializer));
        }

        replace_usages(&sema, edit, &usages, &var_name);

        let insert_before = node_to_insert_before(let_stmt.syntax().clone());
        edit.insert(
            insert_before.text_range().start(),
            "#[derive(PartialEq, Eq)]\nenum Bool { True, False }\n\n".to_string(),
        );
    })
}

/// Replaces all the usages of the converted variable with an equality check
/// against `Bool::True`.
fn replace_usages(
    sema: &hir::Semantics<ra_ide_db::RootDatabase>,
    edit: &mut ActionBuilder,
    usages: &[Reference],
    var_name: &str,
) {
    for usage in usages {
        // Record field shorthands, including the ones inside macro
        // expansions, are replaced via `replace_record_field_expr`, which uses
        // the original source ranges.
        if let Some(record_field) = record_field_for_usage(sema, usage) {
            let replacement = make::expr_from_text(&format!("{} == Bool::True", var_name));
            replace_record_field_expr(sema, edit.text_edit_builder(), &record_field, replacement);
        } else {
            edit.replace(
                usage.file_range.range,
                format!("{} == Bool::True", var_name),
            );
        }
    }
}

/// Converts an expression of type `bool` to one of the new enum type.
fn bool_expr_to_enum_expr(expr: &ast::Expr) -> String {
    if let ast::Expr::Literal(literal) = expr {
        match literal.kind() {
            ast::LiteralKind::Bool(true) => return "Bool::True".to_string(),
            ast::LiteralKind::Bool(false) => return "Bool::False".to_string(),
            _ => (),
        }
    }

    format!("if {} {{ Bool::True }} else {{ Bool::False }}", expr.syntax().text())
}

fn record_field_for_usage(
    sema: &hir::Semantics<ra_ide_db::RootDatabase>,
    usage: &Reference,
) -> Option<ast::RecordField> {
    let file_id = usage.file_range.file_id;
    let offset = usage.file_range.range.start();
    let token = match sema.parse(file_id).syntax().token_at_offset(offset) {
        TokenAtOffset::None => return None,
        TokenAtOffset::Single(token) => token,
        TokenAtOffset::Between(_, token) => token,
    };
    let token = sema.descend_into_macros(token);
    token.parent().ancestors().find_map(ast::RecordField::cast)
}

/// Finds the top-most item which should be preceded by the new enum
/// definition, so that it is inserted inside the right scope.
fn node_to_insert_before(target: SyntaxNode) -> SyntaxNode {
    target
        .ancestors()
        .take_while(|it| !matches!(it.kind(), SyntaxKind::MODULE | SyntaxKind::SOURCE_FILE))
        .filter(|it| ast::ModuleItem::can_cast(it.kind()))
        .last()
        .unwrap_or(target)
}

