fn bool_expr_to_enum_expr(expr: &ast::Expr) -> String {
    if let ast::Expr::Literal(literal) = expr {
        if literal.kind() == ast::LiteralKind::Bool {
            match literal.token().kind() {
                T![true] => return "Bool::True".to_string(),
                T![false] => return "Bool::False".to_string(),
